<?php
require __DIR__.'/layout_start.php';$stats=[];$stats['Produtos']=db()->query('SELECT COUNT(*) FROM tbl_Produtos')->fetchColumn();$stats['Clientes']=db()->query('SELECT COUNT(*) FROM tbl_Clientes')->fetchColumn();$stats['Pedidos']=db()->query('SELECT COUNT(*) FROM tbl_Vendas')->fetchColumn();$stats['Vendas']=db()->query("SELECT COALESCE(SUM(ValorTotal),0) FROM tbl_Vendas WHERE StatusVenda NOT IN ('Cancelado','Pendente')")->fetchColumn();$recent=db()->query("SELECT v.*,c.Nome_Cliente,c.Sobr_Cliente FROM tbl_Vendas v JOIN tbl_Clientes c ON c.ID_Cliente=v.ID_Cliente ORDER BY v.DataVenda DESC LIMIT 7")->fetchAll(); ?>
<div class="eyebrow">ADMINISTRAÇÃO</div><h1>Visão geral.</h1><p style="color:var(--muted);font-size:13px">Acompanhe o ritmo da Byte Zone.</p><div class="stats"><?php foreach($stats as $label=>$value): ?><div class="stat"><small><?= e(strtoupper($label)) ?></small><b><?= $label==='Vendas'?money((float)$value):$value ?></b></div><?php endforeach; ?></div><div class="admin-head"><h2>Pedidos recentes</h2><a class="link-arrow" href="pedidos.php">Ver todos →</a></div><?php if($recent): ?><table class="data-table"><tr><th>Pedido</th><th>Cliente</th><th>Data</th><th>Status</th><th>Total</th></tr><?php foreach($recent as $o): ?><tr><td>#<?= $o['ID_Venda'] ?></td><td><?= e($o['Nome_Cliente'].' '.$o['Sobr_Cliente']) ?></td><td><?= date('d/m/Y H:i',strtotime($o['DataVenda'])) ?></td><td><?= e($o['StatusVenda']) ?></td><td><?= money((float)$o['ValorTotal']) ?></td></tr><?php endforeach; ?></table><?php else: ?><div class="empty">Ainda não há pedidos registrados.</div><?php endif; ?><?php require __DIR__.'/layout_end.php'; ?>
